"""UI 页面注册中心。

提供页面注册与识别功能:

- **register_page** - 注册页面识别函数
- **get_current_page** - 遍历注册表识别当前截图
- **get_registered_pages** - 列出所有已注册页面
- **UIState / record_page_substate** - ``(page, substate)`` 子状态表达（批次 4.1）

导航 / 等待工具函数已迁移至 :mod:`autowsgr.ui.utils`，
此处保留兼容性再导出；子状态模型在 :mod:`autowsgr.ui.stack`。
"""

from __future__ import annotations

import threading
from typing import TYPE_CHECKING

from autowsgr.infra.exceptions import UIVersionError
from autowsgr.infra.logger import get_logger
from autowsgr.ui.stack import UIState, record_page_substate
from autowsgr.ui.utils import (
    DEFAULT_NAV_CONFIG,
    NavConfig,
    NavigationError,
    click_and_wait_for_page,
    click_and_wait_leave_page,
    confirm_operation,
    wait_for_page,
    wait_leave_page,
)
from autowsgr.vision.page_match import PageMatch
from autowsgr.vision.thresholds import NEAR_MISS_EPSILON, PAGE_SCORE_MARGIN


if TYPE_CHECKING:
    from collections.abc import Callable

    import numpy as np


_log = get_logger('ui')

# ---------------------------------------------------------------------------
# 页面注册中心
# ---------------------------------------------------------------------------

_PAGE_REGISTRY: dict[str, Callable[[np.ndarray], PageMatch | bool]] = {}

_RECOGNIZER_ERROR_ESCALATE_THRESHOLD = 5
"""同一识别器连续抛出异常的升级阈值 (R21/3.7)。

连续异常达到该次数后日志级别由 warning 升级为 error；恢复正常即清零。
"""

_recognizer_error_counts: dict[str, int] = {}
"""当前各识别器的连续异常次数 (key=注册名, 恢复后计数为 0)。"""

_PAGE_OBSERVER: Callable[[str | None], None] | None = None
"""页面识别结果观察者（4.5）。

服务器层在启动时注入 ``GameContext.observe_page``，让每次页面识别都成为
前端状态推送的来源。未注入时（golden/单测/脚本）识别行为完全不变。
"""

_page_observer_lock = threading.Lock()


def set_page_observer(observer: Callable[[str | None], None] | None) -> None:
    """注入/清除页面识别观察者；``None`` 表示停止推送。"""
    global _PAGE_OBSERVER
    with _page_observer_lock:
        _PAGE_OBSERVER = observer


def get_page_observer() -> Callable[[str | None], None] | None:
    """返回当前页面观察者（测试/诊断用）。"""
    return _PAGE_OBSERVER


def notify_page_observed(page: str | None) -> None:
    """把一次识别结果交给观察者。

    这里**不做**去重：识别循环每 0.5s 调一次 ``get_current_page``，同一页面
    会重复回调。真正的「只在变化时推」在 ``GameContext.publish_ui_state``
    里按 ``(page, stack, phase, substate)`` 四元组判定 —— 放在那一层才能
    覆盖跨任务基线与导航栈变化，页面层只做无状态转发。
    """
    observer = _PAGE_OBSERVER
    if observer is None:
        return
    try:
        observer(page)
    except Exception:  # noqa: BLE001 - 观察者异常不能影响识别
        _log.opt(exception=True).debug('[UI] 页面观察者异常 (已忽略)')

_OVERLAY_PAGES: set[str] = set()
"""覆盖型页面名集合 (抽屉/浮层)。

这类页面**不遮挡底页的识别元素** (如侧边栏是左侧抽屉, 主页面签名元素在
右侧): 打开时底页签名仍会命中, 且分数往往更高 (主页面 0.988 vs 侧边栏
~0.86)。纯分数排序会把"侧边栏开着"误判为纯主页面, 导致导航在"已到达
侧边栏"与"当前是主页面"之间震荡 — 反复点击切换按钮把侧边栏开了又关,
等待超时 (实机 2026-08-16: 船坞满自动解装的 MAIN→SIDEBAR 死循环)。"""

_ALWAYS_PAGES: set[str] = set()
"""固定纳入识别候选的页面名集合。

这些页面**不在导航图的常规邻域内**, 但任何时刻都可能因为人工干预而成为
当前页 (例如玩家手动换船后停在出征准备页)。若不固定纳入候选集,
:meth:`UIStack.candidates` 算出的邻域里没有它, 识别阶段就会漏判, 转而
命中分数更低的错误页面 (实机 2026-10-24: 准备页 0.932 未注册, 活动页
0.868 的误命中胜出, 触发"点红色 X 关浮层"死循环 15s×N 轮)。"""

UI_VERSION_MAX_SCORE = 0.4
"""全量识别最高分低于该值时，判定为疑似 UI 版本不符（批次 4.3）。

正常可达页面的原始分数普遍在 0.85 以上；连最高分都不到 0.4，通常意味着
游戏客户端更新导致模板整体失效、截图全黑，或整屏被未知弹窗遮挡。
该阈值只用于**全量识别失败后的分级**，不参与正常页面裁决；瞬时加载帧
仍由调用方的重试预算消化，不会因为单帧低分直接中止任务。
"""


def register_page(
    name: str,
    checker: Callable[[np.ndarray], PageMatch | bool],
    *,
    overlay: bool = False,
    always: bool = False,
) -> None:
    """注册页面识别函数。

    checker 宜返回 :class:`~autowsgr.vision.page_match.PageMatch`(携带 score,
    供候选集排序);兼容旧式返回 ``bool`` 的识别器(自动归一化:True→1.0, False→0.0)。

    Parameters
    ----------
    name:
        页面名 (PageName 或纯 str)。
    checker:
        页面识别函数。
    overlay:
        是否为覆盖型页面 (抽屉/浮层, 见 :data:`_OVERLAY_PAGES`)。
        覆盖型页面命中时优先于底页返回 (z-order 优先于分数)。
    always:
        是否固定纳入识别候选 (见 :data:`_ALWAYS_PAGES`)。
        用于"不在导航图上、但任意时刻都可能停留"的页面。
    """
    # Python 3.13+ 中 StrEnum 的 str()/format() 返回 'ClassName.MEMBER' 而非值，
    # 显式提取 .value 确保 key 始终为纯 str，避免日志和比较中出现意外格式。
    key: str = name.value if hasattr(name, 'value') else name
    if key in _PAGE_REGISTRY:
        _log.warning("[UI] 页面 '{}' 已注册，将覆盖", key)
    _PAGE_REGISTRY[key] = checker
    if overlay:
        _OVERLAY_PAGES.add(key)
    else:
        _OVERLAY_PAGES.discard(key)
    if always:
        _ALWAYS_PAGES.add(key)
    else:
        _ALWAYS_PAGES.discard(key)
    # _log.debug("[UI] 注册页面: {}", key)


def _normalize_match(name: str, result: object) -> PageMatch:
    """把识别器返回值归一化为 :class:`PageMatch`。

    兼容三种返回:

    - :class:`PageMatch` —— 直接采用(以注册名覆盖 ``result.name``,防漂移)
    - ``bool`` —— 旧式布尔识别器,True → score=1.0, False → 0.0
    - 其他(如 :class:`~autowsgr.vision.PixelMatchResult`)——
      取 ``.matched`` 与 ``.score``/``.ratio``/``.confidence`` 之一
    """
    if isinstance(result, PageMatch):
        return (
            result
            if result.name == name
            else PageMatch(
                name=name,
                matched=result.matched,
                score=result.score,
                threshold=result.threshold,
            )
        )
    if isinstance(result, bool):
        # 旧式布尔识别器没有"分数/阈值"概念: matched=True 记 1.0, 阈值留空,
        # 因而不参与近失否决 (见 get_current_page)。
        return PageMatch(name=name, matched=result, score=1.0 if result else 0.0)
    matched = bool(getattr(result, 'matched', False))
    raw = getattr(result, 'score', None)
    if raw is None:
        raw = getattr(result, 'ratio', None)
    if raw is None:
        raw = getattr(result, 'confidence', None)
    score = float(raw) if raw is not None else (1.0 if matched else 0.0)
    return PageMatch(name=name, matched=matched, score=score)


def get_current_page(
    screen: np.ndarray,
    candidates: set[str] | None = None,
    *,
    raise_on_total_failure: bool = False,
) -> str | None:
    """识别截图对应的页面名称; 无法判定时返回 ``None`` (UNKNOWN)。

    覆盖型页面 (overlay) 命中时优先于底页返回 — 用户可见/可操作的是覆盖层,
    底页签名同时命中属于预期 (不遮挡)。非覆盖命中集内按 ``score`` 降序取
    最高分(替代旧的"首次匹配即胜"); 分数相同者保持注册(候选)顺序。

    两次"不猜"校验 (**3.4**, 返回 ``None`` 即交给调用方的恢复链):

    1. **margin 校验**: 同一 z-order 池内最高分与次高分相差
       ``< PAGE_SCORE_MARGIN`` (0.05) → 判 UNKNOWN。两个页面几乎同分时,
       按分数排序等于抛硬币; 覆盖型命中时只比覆盖池 (z-order 优先)。
    2. **近失否决**: 某个非覆盖页面未达自身阈值, 但分数落在
       ``[threshold - NEAR_MISS_EPSILON, threshold)`` 且**高于胜者分数**时判
       UNKNOWN。这修复 R23 的实测场景 —— MAIN 模板 0.84 (阈值 0.85) 被判不中,
       而 MAP 标签页 0.62 (阈值 0.60) 判中, 页面被错误地让给低分页。

    Parameters
    ----------
    screen:
        截图 (HxWx3, RGB)。
    candidates:
        候选页面名集合。给出时只评估候选页 —— 导航时可利用"当前页 + 可达页"
        上下文约束,大幅降低不特异签名(如决战页深色背景点)误命中无关页的风险。
        为 ``None`` 时评估全部注册页。
    raise_on_total_failure:
        全量识别最高分低于 :data:`UI_VERSION_MAX_SCORE` 时是否抛
        :class:`~autowsgr.infra.exceptions.UIVersionError`。默认 ``False``，
        保留 UNKNOWN → 调用方恢复链的既有语义；导航层在重试/全量兜底
        仍失败时传 ``True``，把「模板整体失效」与「一时认不出」分开。

    Raises
    ------
    UIVersionError
        仅当 ``raise_on_total_failure=True`` 且最高分 < 0.4 时。
    """
    # 按注册顺序遍历候选(而非候选 set 的任意顺序):同分时稳定排序保持注册顺序,
    # 让旧的"注册顺序优先级"(如 EVENT_MAP 排在 DECISIVE_BATTLE 前)自然融入排序语义。
    reg_order: list[str] = list(_PAGE_REGISTRY.keys())
    if candidates is not None:
        names = [n for n in reg_order if n in candidates]
    else:
        names = reg_order
    matches: list[PageMatch] = []
    failed: list[str] = []
    for name in names:
        checker = _PAGE_REGISTRY.get(name)
        if checker is None:
            continue
        try:
            matches.append(_normalize_match(name, checker(screen)))
        except Exception:
            count = _recognizer_error_counts.get(name, 0) + 1
            _recognizer_error_counts[name] = count
            if count >= _RECOGNIZER_ERROR_ESCALATE_THRESHOLD:
                _log.opt(exception=True).error(
                    "[UI] 页面 '{}' 识别器异常（连续 {} 次）", name, count
                )
            else:
                _log.opt(exception=True).warning(
                    "[UI] 页面 '{}' 识别器异常（连续 {} 次）", name, count
                )
            failed.append(name)
        else:
            previous = _recognizer_error_counts.get(name, 0)
            if previous:
                _recognizer_error_counts[name] = 0
                _log.info(
                    "[UI] 页面 '{}' 识别器恢复正常（此前连续异常 {} 次）",
                    name,
                    previous,
                )

    hits = [m for m in matches if m.matched]
    if hits:
        _log.debug('[UI] 页面识别命中明细: {}', _format_matches(hits))
        # 覆盖型优先 (z-order): 侧边栏开着时主页面也命中且分更高, 但当前页是侧边栏
        overlay_hits = [m for m in hits if m.name in _OVERLAY_PAGES]
        pool = overlay_hits or hits
        # 稳定排序:分数降序,同分保持候选顺序
        pool.sort(key=lambda m: m.score, reverse=True)
        best = pool[0]

        # 3.4 ③ margin: 同一池内几乎同分 → 不猜
        if len(pool) >= 2:
            margin = best.score - pool[1].score
            if margin < PAGE_SCORE_MARGIN:
                _log.warning(
                    '[UI] 页面判定歧义, 判 UNKNOWN: {} (margin={:.3f} < {:.2f})',
                    _format_matches(pool[:2]),
                    margin,
                    PAGE_SCORE_MARGIN,
                )
                notify_page_observed(None)
                return None

        # 3.4 近失否决: 差一点没中的页面分数反而更高 → 不猜
        # (覆盖型命中时不适用: 覆盖层的 z-order 优先于分数)
        if not overlay_hits:
            near_miss = _find_near_miss(matches, best)
            if near_miss is not None:
                _log.warning(
                    '[UI] 近失否决, 判 UNKNOWN: {} 未达阈值但高于胜者 {}',
                    _format_matches([near_miss]),
                    _format_matches([best]),
                )
                notify_page_observed(None)
                return None

        _log.debug(
            '[UI] 当前页面: {} (score={:.3f}, thr={}, 候选 {} / 命中 {})',
            best.name,
            best.score,
            _fmt_threshold(best.threshold),
            len(names),
            len(hits),
        )
        notify_page_observed(best.name)
        return best.name

    ranked = sorted(matches, key=lambda m: m.score, reverse=True)
    max_score = ranked[0].score if ranked else 0.0
    if ranked:
        _log.debug('[UI] 页面识别无命中, Top 分数: {}', _format_matches(ranked[:5]))

    # 批次 4.3：全量识别「全灭」与普通 UNKNOWN 分级。
    # 单帧低分可能只是加载/转场；只有调用方（导航层）在重试预算耗尽后
    # 显式要求分级时，才升级成需要人工更新模板的 UIVersionError。
    if max_score < UI_VERSION_MAX_SCORE:
        top = _format_matches(ranked[:5]) if ranked else '无（所有识别器均未返回结果）'
        log_fn = _log.warning if raise_on_total_failure else _log.debug
        log_fn(
            '[UI] 识别整体失配: 最高分 {:.3f} < {:.2f} (评估 {} 个候选)'
            '，疑似 UI 版本不符；Top: {}',
            max_score,
            UI_VERSION_MAX_SCORE,
            len(names),
            top,
        )
        if raise_on_total_failure:
            notify_page_observed(None)
            raise UIVersionError(
                f'全量识别最高分 {max_score:.3f} < {UI_VERSION_MAX_SCORE:.2f}',
                max_score=max_score,
                threshold=UI_VERSION_MAX_SCORE,
                evaluated=len(names),
                top_matches=[top] if ranked else [],
            )

    if failed:
        _log.warning(
            '[UI] 无匹配页面，且以下识别器抛异常: {} (评估 {} 个候选)',
            failed,
            len(names),
        )
    else:
        _log.debug('[UI] 当前页面: 无匹配 (评估 {} 个候选)', len(names))
    notify_page_observed(None)
    return None


def _fmt_threshold(threshold: float | None) -> str:
    """格式化阈值: 未知来源显示 ``-``。"""
    return '-' if threshold is None else f'{threshold:.2f}'


def _format_matches(matches: list[PageMatch]) -> str:
    """把 PageMatch 列表格式化为 ``名称=分数/thr=阈值`` (命中项带 ``*``)。"""
    return ', '.join(
        f'{m.name}={m.score:.3f}/thr={_fmt_threshold(m.threshold)}{"*" if m.matched else ""}'
        for m in matches
    )


def _find_near_miss(matches: list[PageMatch], best: PageMatch) -> PageMatch | None:
    """返回"差一点没中、分数却高于胜者"的非覆盖页面 (最近失)。

    覆盖型页面按 z-order 判定, 不参与否决; 阈值未知的旧式识别器也不参与。
    """
    candidates = [
        m
        for m in matches
        if not m.matched
        and m.threshold is not None
        and m.name not in _OVERLAY_PAGES
        and m.score > best.score
        and m.score + NEAR_MISS_EPSILON >= m.threshold
    ]
    if not candidates:
        return None
    return max(candidates, key=lambda m: m.score)


def get_registered_pages() -> list[str]:
    """返回所有已注册的页面名称列表。"""
    return list(_PAGE_REGISTRY.keys())


def get_recognizer_errors() -> dict[str, int]:
    """返回当前连续识别器异常计数快照 (key=注册名, 恢复后计数为 0)。"""
    return _recognizer_error_counts.copy()


def get_always_pages() -> set[str]:
    """返回固定纳入识别候选的页面名集合 (见 :data:`_ALWAYS_PAGES`)。"""
    return set(_ALWAYS_PAGES)


def dump_page_scores(screen: np.ndarray) -> list[tuple[str, float, bool, float | None]]:
    """对全部注册页跑一遍识别, 返回 ``[(页面名, score, matched, threshold), ...]`` (按分数降序)。

    仅供**识别失败时的现场取证**: 正常流程不要调用 (全表扫描开销大)。
    识别器现在返回**原始分数** (未达阈值也保留, 见 3.4), 因此日志能区分:

    - ``某页 0.93 但没注册/没进候选`` —— 不在表里;
    - ``最高分只有 0.55`` 差一口气 —— 表里能看到 0.55 以及它需要的阈值;
    - ``某页识别器抛异常`` —— ``score=-1.0``。
    """
    rows: list[tuple[str, float, bool, float | None]] = []
    for name, checker in _PAGE_REGISTRY.items():
        try:
            pm = _normalize_match(name, checker(screen))
        except Exception:
            _log.opt(exception=True).debug("[UI] 页面 '{}' 取证识别器异常", name)
            rows.append((name, -1.0, False, None))
            continue
        rows.append((name, pm.score, pm.matched, pm.threshold))
    rows.sort(key=lambda r: r[1], reverse=True)
    return rows


def format_page_scores(
    rows: list[tuple[str, float, bool, float | None]],
    *,
    top: int | None = None,
) -> str:
    """把 :func:`dump_page_scores` 的结果格式化为一行日志。

    ``*`` = 命中, ``thr=-`` = 阈值来源未知(旧式识别器), ``score=-1.000`` = 识别器异常。
    失败现场必须能回答「差多少」——这是 §9.3 取证纪律的第 1 条。
    """
    items = rows if top is None else rows[:top]
    return ', '.join(
        f'{name}={score:.3f}/thr={_fmt_threshold(threshold)}{"*" if matched else ""}'
        for name, score, matched, threshold in items
    )


